  const capacities = (policy && policy.capacities) || {};
  return {
    ...restaurant,
    tables: (restaurant.tables || []).map((t) =>
      (Number.isInteger(capacities[t.id]) ? { ...t, capacity: capacities[t.id] } : t)),
  };
}
